// SPDX-License-Identifier: MIT
pragma solidity ^0.8.27;

/**
 * @title StakingConstants
 * @dev Contract containing constants for staking system
 * These constants can be inherited or referenced by other contracts
 */
contract StakingConstants {
    uint256 public constant SECONDS_PER_YEAR = 365 days;
    uint256 public constant BASIS_POINTS = 10000; // 100% = 10000
    uint256 public constant PRECISION = 1e18;
    uint256 public constant LOCK_PERIOD = 365 days;
    uint256 public constant HSK_DECIMALS = 18; // HSK token decimals
    uint256 public constant EARLY_UNLOCK_PERIOD = 7 days;  // Early unlock waiting period
    uint256 public constant EARLY_UNSTAKE_REWARD_RETAIN_RATE = 5000;  // Early unstake reward retain rate (50% = 5000 basis points, user retains 50% of rewards)
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.27;

import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/access/Ownable2StepUpgradeable.sol";
import "../interfaces/IStake.sol";

/**
 * @title StakingStorage
 * @dev Defines the storage layout for the staking contract
 * This contract contains all state variables used in the staking system
 * and handles their initialization
 */
abstract contract StakingStorage is Initializable, Ownable2StepUpgradeable {
    uint256 public minStakeAmount;
    uint256 public totalStaked;
    uint256 public nextPositionId;
    uint256 public rewardRate;

    mapping(uint256 => IStaking.Position) public positions;
    mapping(address => uint256[]) public userPositions;

    bool public emergencyMode;

    uint256 public totalPendingRewards;
    uint256 public rewardPoolBalance;

    mapping(address => bool) public whitelisted;

    uint256 public stakeStartTime;
    uint256 public stakeEndTime;
    bool public onlyWhitelistCanStake;

    uint256 public maxTotalStaked;

    // Early unstake related storage

    mapping(uint256 => uint256) public claimedRewards;  // positionId => Total claimed rewards
    mapping(uint256 => uint256) public earlyUnstakeRequestTime;  // positionId => Early unstake request time (0 means not requested)

    address public penaltyPoolContract;          // Penalty pool contract address

    uint256[50] private __gap;

    event RewardPoolUpdated(uint256 newBalance);
    event RewardRateUpdated(uint256 oldRate, uint256 newRate);

    /**
     * @dev Initializes the storage contract with basic settings
     * @param _owner Address of the contract owner
     * @param _minStakeAmount Minimum stake amount (in wei)
     * @param _rewardRate Annual reward rate in basis points (800 for 8%, 1600 for 16%)
     * @param _whitelistMode Enable whitelist mode (true for Premium, false for Normal)
     * @param _maxTotalStaked Maximum total staked amount (in wei, 0 means no limit)
     * @param _penaltyPoolContract Address of the penalty pool contract
     */
    function __StakingStorage_init(
        address _owner,
        uint256 _minStakeAmount,
        uint256 _rewardRate,
        bool _whitelistMode,
        uint256 _maxTotalStaked,
        address _penaltyPoolContract
    ) internal onlyInitializing {
        require(_owner != address(0), "StakingStorage: zero owner");
        require(_minStakeAmount > 0, "Invalid min stake amount");
        require(_rewardRate > 0 && _rewardRate <= 10000, "Invalid reward rate");
        require(_penaltyPoolContract != address(0), "StakingStorage: zero penalty pool");

        __Ownable_init(_owner);

        minStakeAmount = _minStakeAmount;
        rewardRate = _rewardRate;
        nextPositionId = 1;
        maxTotalStaked = _maxTotalStaked;
        penaltyPoolContract = _penaltyPoolContract;

        stakeStartTime = type(uint256).max;
        stakeEndTime = type(uint256).max;
        onlyWhitelistCanStake = _whitelistMode;
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.27;

/**
 * @title IPenaltyPool
 * @dev Interface for the penalty pool contract
 */
interface IPenaltyPool {
    event PenaltyDeposited(address indexed depositor, uint256 amount, uint256 timestamp);
    event PenaltyWithdrawn(address indexed to, uint256 amount, uint256 timestamp);
    event AuthorizedDepositorUpdated(address indexed oldDepositor, address indexed newDepositor);

    function deposit() external payable;
    function withdraw(address payable to, uint256 amount) external;
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.27;

interface IStaking {
    struct Position {
        uint256 positionId;      // Position ID
        address owner;           // Position owner
        uint256 amount;          // Staked amount
        uint256 stakedAt;        // Timestamp when staked
        uint256 lastRewardAt;    // Last reward claim timestamp
        bool isUnstaked;         // Whether position is unstaked
        bool isCompletedStake;   // Whether position completed full staking period (via unstake)
    }

    function stake() external payable returns (uint256 positionId);

    function unstake(uint256 positionId) external;

    function claimReward(uint256 positionId) external returns (uint256 reward);

    function pendingReward(uint256 positionId) external view returns (uint256 reward);

    function getUserPositionIds(address user) external view returns (uint256[] memory);

    function calculatePotentialReward(uint256 amount) external view returns (uint256);

    function requestEarlyUnstake(uint256 positionId) external;

    function completeEarlyUnstake(uint256 positionId) external;

    event PositionCreated(
        address indexed user,
        uint256 indexed positionId,
        uint256 amount,
        uint256 lockPeriod,
        uint256 timestamp
    );

    event PositionUnstaked(
        address indexed user,
        uint256 indexed positionId,
        uint256 amount,
        uint256 timestamp
    );

    event RewardClaimed(
        address indexed user,
        uint256 indexed positionId,
        uint256 amount,
        uint256 timestamp
    );

    event StakingPaused(address indexed operator, uint256 timestamp);

    event StakingUnpaused(address indexed operator, uint256 timestamp);

    event EmergencyWithdrawn(
        address indexed user,
        uint256 indexed positionId,
        uint256 amount,
        uint256 timestamp
    );

    event EarlyUnstakeRequested(
        address indexed user,
        uint256 indexed positionId,
        uint256 timestamp
    );

    event EarlyUnstakeCompleted(
        address indexed user,
        uint256 indexed positionId,
        uint256 principal,
        uint256 reward,
        uint256 penalty,
        uint256 timestamp
    );
}

